{
    CThingSwitchDef def; g_manager.Def = &def; g_manager.Index = -1;
    CThingSwitch sw; sw.DefGlobalIndex = 0x1F;
    {
        CDefPointer<const CThingSwitchDef> p = sw.PeekDefinition();
        CHECK(p.Object == &def && g_manager.Index == 0x1F && def.Refs == 2);
    }
    CHECK(def.Refs == 1);
    g_manager.Def = 0;
